#!/bin/sh
# Opereta 계정 관리 헬퍼. operetad 가 systemd-run --pipe 로 부르며 root 로 실행된다.
#
# operetad 자신은 ProtectSystem 과 ProtectHome 아래에서 돌아 /etc 와 /home 에 쓸 수 없다. 그래서 계정을 만들고
# 지우는 일은 하드닝이 없는 이 헬퍼가 맡는다. 비밀번호는 표준 입력의 첫 줄로만 받으며 인자나 파일에 남기지 않는다.
#
# 사용법: opereta-user add NAME [--admin]   (비밀번호를 표준 입력 첫 줄에 준다)
#         opereta-user remove NAME
#         opereta-user ssh-prepare   (없는 SSH 호스트 키를 만들고 로그인 허용 정책을 맞춘다)
# 결과는 표준 출력의 마지막 줄 OPERETA_USER_RESULT=ok 또는 OPERETA_USER_RESULT=error:<코드> 로 알린다.
# 환경 변수는 테스트용이다: OPERETA_USER_LIST, OPERETA_SSHD_DROPIN, OPERETA_USER_GROUPS, OPERETA_SYSTEMD_DIR.
set -u
# 문자 범위가 로케일에 따라 달라지지 않게 고정한다.
LC_ALL=C
export LC_ALL

LIST="${OPERETA_USER_LIST:-/var/lib/opereta/users.list}"
DROPIN="${OPERETA_SSHD_DROPIN:-/etc/ssh/sshd_config.d/50-opereta.conf}"
GROUPS_BASE="${OPERETA_USER_GROUPS:-opereta,video,render}"
# systemd 가 실제로 부팅한 시스템에만 있는 디렉터리다. 설치기의 chroot 에는 없다.
SYSTEMD_DIR="${OPERETA_SYSTEMD_DIR:-/run/systemd/system}"

result_ok() { echo 'OPERETA_USER_RESULT=ok'; exit 0; }
result_err() {
    echo "opereta-user: $2" >&2
    echo "OPERETA_USER_RESULT=error:$1"
    exit 1
}

# 이름 규칙: 소문자로 시작, 소문자, 숫자, 밑줄, 하이픈, 최대 32자. 시스템과 Opereta 예약어는 거절한다.
valid_name() {
    case "$1" in
        '' | *[!abcdefghijklmnopqrstuvwxyz0123456789_-]* | [!abcdefghijklmnopqrstuvwxyz]*) return 1 ;;
    esac
    [ "${#1}" -le 32 ] || return 1
    case "$1" in
        root | user | nobody | daemon | bin | sys | sync | games | man | lp | mail | news | uucp | proxy | www-data \
            | backup | list | irc | sshd | opereta* | systemd* | messagebus | polkitd | greetd | tuigreet | lightdm) return 1 ;;
    esac
    return 0
}

# 비밀번호: 8~128자, 제어 문자 없음, 이름과 달라야 한다.
valid_password() {
    pw="$1"
    [ "${#pw}" -ge 8 ] && [ "${#pw}" -le 128 ] || return 1
    case "$pw" in
        *[![:print:]]*) return 1 ;;
    esac
    [ "$pw" != "$2" ]
}

in_list() { [ -f "$LIST" ] && awk -v n="$1" '$1 == n { f = 1 } END { exit !f }' "$LIST"; }

# 관리하는 계정 목록에서 sshd 드롭인을 다시 만든다. 계정이 없으면 드롭인을 지운다.
write_policy() {
    names=''
    if [ -f "$LIST" ]; then
        names="$(awk '{ printf "%s ", $1 }' "$LIST")"
    fi
    dropin_dir="$(dirname "$DROPIN")"
    if [ -z "$names" ]; then
        rm -f "$DROPIN"
        return 0
    fi
    [ -d "$dropin_dir" ] || mkdir -p "$dropin_dir"
    tmp="${DROPIN}.tmp.$$"
    {
        echo '# Generated by opereta-user. Do not edit; changes are overwritten.'
        echo '# Password login is allowed only for the accounts created through Opereta.'
        echo 'PasswordAuthentication yes'
        echo 'PermitRootLogin no'
        echo "AllowUsers ${names% }"
    } > "$tmp"
    chmod 644 "$tmp"
    mv -f "$tmp" "$DROPIN"
    return 0
}

reload_ssh() {
    # 설치기가 대상 시스템의 chroot 안에서 부를 때는 서비스도 호스트 키도 없다. 그때는 검증과 다시 읽기를 건너뛴다.
    [ -d "$SYSTEMD_DIR" ] || return 0
    command -v systemctl >/dev/null 2>&1 || return 0
    if systemctl is-active --quiet ssh.service 2>/dev/null; then
        if command -v sshd >/dev/null 2>&1 && ! sshd -t 2>/dev/null; then
            rm -f "$DROPIN"
            result_err ssh_config 'sshd rejected the generated configuration; it was removed'
        fi
        systemctl reload ssh.service >/dev/null 2>&1 || true
    fi
    return 0
}

cmd_add() {
    name="${1:-}"
    admin=0
    [ "${2:-}" = '--admin' ] && admin=1
    valid_name "$name" || result_err invalid_username 'the user name is not allowed'
    IFS= read -r password || password=''
    valid_password "$password" "$name" || result_err invalid_password 'the password must be 8 to 128 printable characters and differ from the user name'
    if getent passwd "$name" >/dev/null 2>&1 || in_list "$name"; then
        result_err user_exists 'the account already exists'
    fi
    groups="$GROUPS_BASE"
    [ "$admin" -eq 1 ] && groups="${groups},sudo"
    useradd --create-home --shell /bin/bash --groups "$groups" --comment 'Opereta user' "$name" \
        || result_err account_failed 'useradd failed'
    if ! printf '%s:%s\n' "$name" "$password" | chpasswd; then
        userdel "$name" >/dev/null 2>&1
        result_err account_failed 'setting the password failed; the account was removed'
    fi
    password=''
    mkdir -p "$(dirname "$LIST")"
    printf '%s %s %s\n' "$name" "$admin" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$LIST"
    write_policy
    reload_ssh
    result_ok
}

cmd_remove() {
    name="${1:-}"
    valid_name "$name" || result_err invalid_username 'the user name is not allowed'
    in_list "$name" || result_err user_not_found 'the account was not created through Opereta'
    # 홈 디렉터리는 지우지 않는다. 데이터를 잃지 않도록 계정만 지운다.
    if getent passwd "$name" >/dev/null 2>&1; then
        userdel "$name" || result_err account_failed 'userdel failed'
    fi
    tmp="${LIST}.tmp.$$"
    awk -v n="$name" '$1 != n' "$LIST" > "$tmp"
    mv -f "$tmp" "$LIST"
    write_policy
    reload_ssh
    result_ok
}

# operetad 는 /etc 에 쓸 수 없으므로 SSH 호스트 키 생성과 정책 파일도 이 헬퍼가 맡는다.
# 이미 있는 호스트 키는 바꾸지 않는다(ssh-keygen -A 는 없는 키만 만든다).
cmd_ssh_prepare() {
    if command -v ssh-keygen >/dev/null 2>&1; then
        ssh-keygen -A >/dev/null 2>&1 || result_err ssh_keys 'ssh-keygen -A failed'
    fi
    write_policy
    reload_ssh
    result_ok
}

case "${1:-}" in
    add) shift; cmd_add "$@" ;;
    remove) shift; cmd_remove "$@" ;;
    ssh-prepare) cmd_ssh_prepare ;;
    *) result_err usage 'usage: opereta-user add NAME [--admin] | remove NAME | ssh-prepare' ;;
esac
